const ideas = $('Sheets — Lire idées social').all().map(i => i.json);
const calendar = $('Sheets — Calendrier existant').all().map(i => i.json);

const newIdeas = ideas.filter(i => i.Status === 'nouveau' || i.Status === 'validé');
const existingSubjects = calendar.map(c => c.Sujet).filter(Boolean);

return [{
  json: {
    available_ideas: newIdeas.slice(0, 20),
    existing_subjects: existingSubjects,
    week_start: new Date(Date.now() + 86400000).toISOString().split('T')[0]
  }
}];

const response = $input.first().json;

let parsed;
try {
  const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Erreur parsing calendrier: ' + e.message);
}

const rows = [];
const weekNum = Math.ceil((new Date().getTime() - new Date(new Date().getFullYear(), 0, 1).getTime()) / (7 * 86400000));

for (const day of (parsed.calendar || [])) {
  for (const post of (day.posts || [])) {
    rows.push({
      Semaine: `S${weekNum}`,
      Jour: day.day,
      Date: day.date,
      Heure_GMT: post.time,
      Reseau: post.network,
      Format: post.format,
      Rubrique: post.rubrique,
      Sujet: post.subject,
      Contenu: post.hook,
      Media_URL: '',
      Hashtags: (post.hashtags || []).join(' '),
      Status_Contenu: 'à_produire',
      Status_Media: post.media_needed !== 'none' ? 'à_produire' : 'n/a',
      Status_Publication: 'planifié',
      URL_Post: '',
      Media_Prompt: post.media_prompt || ''
    });
  }
}

return rows.map(r => ({ json: r }));
